def crc(data,poly,init,refin,refout,xorout,w=32):
    r=init
    if refin:
        # reflected
        pr=int(bin(poly)[2:].zfill(w)[::-1],2)
        r=int(bin(init)[2:].zfill(w)[::-1],2) if False else init
        for b in data:
            r^=b
            for _ in range(8): r=(r>>1)^pr if r&1 else r>>1
        return r^xorout
    for b in data:
        r^=b<<(w-8)
        for _ in range(8): r=((r<<1)^poly if r&0x80000000 else r<<1)&0xffffffff
    return r^xorout
